import time


class Rate:
    """统一的ROS频率控制类，适用于ROS1和ROS2

    使用高精度时钟和时间漂移补偿，提供更精确的频率控制
    """

    def __init__(self, frequency: float):
        """初始化Rate对象

        Args:
            frequency: 频率 (Hz)
        """
        if frequency <= 0:
            raise ValueError("Frequency must be positive")
        self.frequency = frequency
        self.period = 1.0 / frequency
        self.start_time = time.perf_counter()
        self.next_time = self.start_time + self.period
        self.cycle_count = 0

    def sleep(self):
        """睡眠以维持设定的频率，使用时间漂移补偿"""
        current_time = time.perf_counter()
        sleep_duration = self.next_time - current_time

        if sleep_duration > 0:
            if sleep_duration > 0.001:
                time.sleep(sleep_duration - 0.0001)

            while time.perf_counter() < self.next_time:
                pass

        self.cycle_count += 1
        self.next_time = self.start_time + (self.cycle_count + 1) * self.period


__all__ = ["Rate"]
